struct EmptyTag {};

// Empty Base Optimization (EBO) applies
// Tag consumes 0 bytes when derived
struct Optimized : EmptyTag {
    int id;
    // Zero-Sized Array (ZSA - often used for FAM proxy)
    // Takes 0 bytes, only provides access/alignment
    char data[0];
};

// Non-EBO comparison (member vs base)
struct NonOptimized {
    EmptyTag t;
    int id;
    char data[0];
};

// Example Sizes (assuming standard alignment):
// sizeof(Optimized)      == 4
// sizeof(NonOptimized)   >= 8 (Tag member must be allocated 1 byte + padding)
